(function(){'use strict';var field=document.querySelector('[data-murtadd-wordcount]');if(field&&window.murtaddMeta){var counter=field.parentElement.querySelector('.murtadd-wordcount');var update=function(){var words=field.value.trim()?field.value.trim().split(/\s+/).length:0;var over=words>murtaddMeta.wordCap;counter.textContent=words+' '+murtaddMeta.wordsLabel+(over?' — '+murtaddMeta.capWarning:'');counter.style.color=over?'#8a4b00':'';};field.addEventListener('input',update);update();}
var repeater=document.getElementById('murtadd-sources-repeater');var addBtn=document.getElementById('murtadd-add-source');if(repeater&&addBtn){addBtn.addEventListener('click',function(){var row=repeater.querySelector('.murtadd-source-row').cloneNode(true);row.querySelectorAll('input').forEach(function(i){i.value='';});repeater.appendChild(row);});repeater.addEventListener('click',function(e){if(e.target.classList.contains('murtadd-remove-source')&&repeater.querySelectorAll('.murtadd-source-row').length>1){e.target.closest('.murtadd-source-row').remove();}});}}());